package com.chubb.apac.claims.modulith.inforequest.controller;
import com.chubb.apac.claims.modulith.common.enums.*;import com.chubb.apac.claims.modulith.common.security.CurrentUser;import com.chubb.apac.claims.modulith.inforequest.dto.request.CreateInformationRequest;import com.chubb.apac.claims.modulith.inforequest.dto.response.InformationRequestResponse;import com.chubb.apac.claims.modulith.inforequest.model.InformationRequestStatus;import com.chubb.apac.claims.modulith.inforequest.service.InformationRequestService;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;import java.time.LocalDate;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.core.MethodParameter;import org.springframework.http.MediaType;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.web.context.request.NativeWebRequest;import org.springframework.web.method.support.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class StaffInformationRequestControllerTest {InformationRequestService service;MockMvc mvc;ObjectMapper mapper;
 @BeforeEach void setup(){service=mock(InformationRequestService.class);CurrentUser user=new CurrentUser("S1","s@b.com",Set.of(UserRole.CLAIMS_STAFF),Set.of(Market.SG),"T1");HandlerMethodArgumentResolver resolver=new HandlerMethodArgumentResolver(){public boolean supportsParameter(MethodParameter p){return p.hasParameterAnnotation(AuthenticationPrincipal.class)&&p.getParameterType().equals(CurrentUser.class);}public Object resolveArgument(MethodParameter p,ModelAndViewContainer m,NativeWebRequest w,org.springframework.web.bind.support.WebDataBinderFactory b){return user;}};mvc=MockMvcBuilders.standaloneSetup(new StaffInformationRequestController(service)).setCustomArgumentResolvers(resolver).build();mapper=new ObjectMapper().registerModule(new JavaTimeModule());}
 @Test void createReturns201()throws Exception{var out=new InformationRequestResponse("IRQ-1","CLM-1",List.of("Invoice"),LocalDate.now(),InformationRequestStatus.PENDING,null,null,"S1",List.of());when(service.create(any(),any(),any(),any(),any())).thenReturn(out);var request=new CreateInformationRequest(List.of("Invoice"),LocalDate.now(),null);mvc.perform(post("/api/v1/staff/claims/CLM-1/info-requests").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(request))).andExpect(status().isCreated()).andExpect(jsonPath("$.data.requestId").value("IRQ-1"));}}
